import{_ as t,H as e,f as r,i as a}from"./chunks/framework.Cvt1eIE0.js";const l=JSON.parse('{"title":"第三章 王の運命の出会い","description":"","frontmatter":{},"headers":[],"relativePath":"story/4-3.md","filePath":"story/4-3.md"}'),o={name:"story/4-3.md"};function s(_,p,n,i,c,d){return e(),r("div",null,[...p[0]||(p[0]=[a('<h1 id="第三章-王の運命の出会い" tabindex="-1">第三章 王の運命の出会い <a class="header-anchor" href="#第三章-王の運命の出会い" aria-label="Permalink to &quot;第三章 王の運命の出会い&quot;">​</a></h1><p>「ありがとうございます。」</p><p>少女は、優しく微笑んだ。</p><p>夕日に照らされた噴水広場。本のページが、風のないはずの街で、熱気に押されるようにわずかにめくれた気がした。</p><p>オーレックスは、しばらく言葉が出なかった。</p><p>「あの……？」</p><p>「あっ！」</p><p>「ご、ごめん。」</p><p>「本が多いね。」</p><p>ようやく口を開いた言葉は、ひどく当たり前のものだった。けれど、それが今は、何より大事な言葉に思えた。</p><p>少女は、少し恥ずかしそうに笑った。</p><p>「王立図書館で借りてきたんです。」</p><p>「本が好きで。」</p><p>「そうなんだ。」</p><p>「僕も好きだよ。」</p><p>「本当ですか？」</p><p>少女の顔が、ぱっと明るくなった。噴水の光よりも、ずっと眩しかった。</p><p>「歴史書とか？」</p><p>「冒険記とか。」</p><p>「あと、古代文明の本も。」</p><p>「えっ！」</p><p>「私もです！」</p><p>二人は、思わず笑った。世界の広さに対して、好きなものが重なる確率は、決して高くないはずだった。それでも、こうして重なってしまうことが、ある。</p><hr><p>「私はリリア。」</p><p>「リリア・フローレンスです。」</p><p>「僕は……。」</p><p>オーレックスは、一瞬、考えた。</p><p>名乗るべき名前は、決まっていた。けれど、その名を口にする瞬間、ほんの少しだけ、胸の奥がざわついた。嘘をついているわけではない。ただ、今だけは「王」ではなく、ただの「誰か」として、この出会いを大事にしたかった。</p><p>「レックス。」</p><p>「親衛隊の兵士。」</p><p>「レックスさん。」</p><p>リリアは、微笑んだ。</p><p>「ありがとうございます。」</p><p>「助かりました。」</p><p>「いや。」</p><p>「こちらこそ。」</p><p>「楽しかった。」</p><p>「え？」</p><p>「いや、なんでもない。」</p><p>リリアは、くすっと笑った。</p><p>「変な人ですね。」</p><p>「よく言われる。」</p><p>それは、本当のことだった。ピックバーグにも、スターリンにも、よく言われる。今日だけは、それが「王として」ではなく「ただのレックスとして」言われたことが、たまらなく愉快だった。</p><p>「ふふふ。」</p><p>二人は、笑い合った。</p><hr><p>気付けば、空は赤く染まっていた。グロウベリーの光と、夕焼けの色が混ざり合い、噴水の周りだけ、世界がほんの少し優しい色をしていた。</p><p>「大変！」</p><p>「もうこんな時間！」</p><p>リリアは、慌てて本を抱え直した。</p><p>「これ、ありがとうございました。」</p><p>本を受け取りながら、オーレックスは、ふと、その一冊の隙間に、小さな何かが挟まっているのを見た気がした。けれど、それを確かめる前に、リリアは、もう一度、こちらを見上げていた。</p><p>「また会えますか？」</p><p>その言葉に、オーレックスは目を丸くした。</p><p>「え？」</p><p>「あっ！」</p><p>「その……。」</p><p>「今日、お話して楽しかったから。」</p><p>「迷惑でしたか？」</p><p>「そんなことない！」</p><p>オーレックスは、思わず大声を出した。普段の彼を知る者が聞けば、誰もが驚くような声量だった。</p><p>「ぜひ！」</p><p>「また会いたい！」</p><p>「……。」</p><p>今度は、リリアが驚いていた。</p><p>そして、二人は笑った。</p><p>「じゃあ。」</p><p>「また。」</p><p>「うん。」</p><p>「また。」</p><p>そう言って、少女は、夕暮れの街へ消えていった。</p><p>歩いていく後ろ姿が、橙色の光の中に、ゆっくりと溶けていった。</p><p>その姿が見えなくなってから、ようやく、オーレックスは自分の手の中に視線を落とした。本の隙間から、小さな押し花の栞が、はらりと落ちていた。それを、慌てて拾い上げ、上着の内側に、そっとしまった。気づかれなかったことに、少しだけ、安堵した。</p><hr><p>その頃。</p><p>王宮。</p><p>「終わったぁぁ！」</p><p>レッドは、机に突っ伏していた。冠が、机の端で、かたんと音を立てた。</p><p>「もう二度と王様なんてやりません！」</p><p>スターリンは、大笑いしていた。</p><p>「はっはっは！」</p><p>「いい経験だったろ！」</p><p>「寿命が縮みました！」</p><p>「お疲れ様。」</p><p>ピックバーグは、苦笑した。山のような書類の中に、判の押し間違いが何箇所かあったが、それは、また後で直せばいい話だった。</p><p>すると。</p><p>王宮の扉が開いた。</p><p>「ただいま。」</p><p>オーレックスが帰ってきた。</p><p>「おう！」</p><p>スターリンが振り向く。</p><p>「どうだった？」</p><p>「兵士生活は？」</p><p>「楽しかった？」</p><p>「うん。」</p><p>「すごく。」</p><p>オーレックスは、珍しく笑顔だった。それも、戦に勝った時の達成感とは、まったく違う種類の笑顔だった。</p><p>「……？」</p><p>スターリンとピックバーグは、顔を見合わせた。</p><p>「なんだ？」</p><p>「様子が変じゃないか？」</p><p>「まさか。」</p><p>ピックバーグが、目を細めた。観察者の目が、何か小さな違和感を、見逃さなかった。</p><p>「……。」</p><p>「いや。」</p><p>「まさかね。」</p><p>二人は、そこで言葉を止めた。長年の付き合いで分かることもあれば、わざと聞かないでおくべきことも、ある。今夜は、後者だった。</p><hr><p>翌朝。</p><p>王宮の庭園。</p><p>朝の光が、グロウベリーの蔓に滲んで、淡い金色を散らしていた。</p><p>オーレックスは、昨日もらった栞を、そっと眺めていた。</p><p>本の間から落ちてきた、小さな押し花の栞。</p><p>リリアのものだった。乾いた花弁は、もう色を失いかけていたが、それでもどこか、温かみを残していた。</p><p>「……。」</p><p>自然と、笑みがこぼれる。</p><p>すると。</p><p>「陛下。」</p><p>ピックバーグが現れた。</p><p>「朝からニヤニヤして。」</p><p>「気持ち悪いよ。」</p><p>「え！？」</p><p>「してない！」</p><p>「してる。」</p><p>「してない！」</p><p>「してる。」</p><p>「してないって！」</p><p>そのやり取りを見て、スターリンが吹き出した。</p><p>「はっはっは！」</p><p>「こいつ！」</p><p>「恋してやがる！」</p><p>「違う！！」</p><p>「顔真っ赤だぞ！」</p><p>「違うってば！」</p><p>王宮中に、笑い声が響いた。</p><p>戦争のない朝。</p><p>穏やかな風。</p><p>そして。</p><p>黄金王の、少しだけ特別な毎日。</p><p>英雄たちにも、こんな平和な時間は必要なのかもしれない。剣を握り続けてきた手のひらに、今は、小さな栞だけが、そっと収まっていた。</p><hr><p>数年後。</p><p>歴史家たちは、この日をこう呼ぶことになる。</p><p>「黄金王と王妃の、最初の出会いの日」</p><p>と。</p><p>しかし。</p><p>今のオーレックスは、まだ知らない。</p><p>この少女と共に、笑い、泣き、支え合い、未来を歩んでいくことを。</p><p>そして。</p><p>二人の子供たちが、次の時代を担うことを。</p><p>それは、もう少し先のお話。</p><p>今はただ。</p><p>一枚の栞と、一つの約束だけが、確かに、ここにあった。</p><hr><p>PIGLIN KING</p><p>第四巻 ささやかな日常と小さないたずら</p><p>完</p>',158)])])}const f=t(o,[["render",s]]);export{l as __pageData,f as default};
